int reject_key_and_link(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    if (!key || !keyring) {
        return -EINVAL;
    }

    if (key->type->reject || key->type->instantiate) {
        return -EINVAL;
    }

    if (key->state != KEY_STATE_REVOKED && key->state != KEY_STATE_INSTANTIATED) {
        return -EINVAL;
    }

    key->state = KEY_STATE_NEGATIVE;

    if (timeout) {
        key->expiry = getnstime_monotonic() + timeout * NSEC_PER_SEC;
        key->flags |= 1 << KEY_FLAG_EXPIRE;
    }

    if (keyring) {
        if (key->dest_keyring) {
            return -EINVAL;
        }

        key->dest_keyring = keyring_get(keyring);

        if (!key->dest_keyring) {
            return -ENOMEM;
        }

        keyring->usage++;
    }

    if (authkey) {
        key_revoke(authkey);
    }

    key->error = error;

    if (key->state == KEY_STATE_INSTANTIATED) {
        key->state = KEY_STATE_NEGATIVE;
        key->flags |= 1 << KEY_FLAG_NEGATIVE;
    }

    key->flags |= 1 << KEY_FLAG_TIMEOUT;

    schedule_key_gc();

    if (key->wait) {
        wake_up(key->wait);
    }

    return 0;
}
